class Solution {
    private int digitSum(int value){
        int sum=0;
        while(value>0){
            sum+=value%10;
            value/=10;
        }
        return sum;
    }
    public int maximumSum(int[] nums){
        Map<Integer,Integer> maximum=new HashMap<>();
        int answer=-1;
        for(int value:nums){
            int sum=digitSum(value);
            if(maximum.containsKey(sum))answer=Math.max(answer,value+maximum.get(sum));
            maximum.put(sum,Math.max(maximum.getOrDefault(sum,0),value));
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maximumSum(nums:IntArray):Int{
        val maximum=HashMap<Int,Int>();
        var answer=-1;
        for(value in nums){
            var x=value;
            var sum=0;
            while(x>0){
                sum+=x%10;
                x/=10
            };
            maximum[sum]?.let{
                answer=maxOf(answer,value+it)
            };
            maximum[sum]=maxOf(maximum[sum]?:0,value)
        };
        return answer
    }
}

